bash -lc /bin/bash -lc "node --input-type=module - <<'JS'
import { DuckDBInstance } from '@duckdb/node-api';
const db = await DuckDBInstance.create(':memory:', {threads:'4', memory_limit:'2GB'});
const c = await db.connect();
for (const sql of [
  \"select version() as version\",
  \"select count(*) n, count(distinct county_fips) counties, min(year) min_year, max(year) max_year from read_parquet('upload/county_year_panel.parquet')\",
  \"describe select * from read_parquet('upload/county_year_panel.parquet')\",
  \"select * from parquet_metadata('upload/county_year_panel.parquet') limit 3\"
]) {
 const rr = await c.runAndReadAll(sql); console.log(JSON.stringify(rr.getRowObjectsJson()));
}
JS"

